pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 recordedAfterDeposit;
        try c.getBalance(address(this)) returns (uint256 __r) { recordedAfterDeposit = __r; } catch { return; }
        uint contractEtherAfterDeposit = address(c).balance;
        uint callerEtherAfterDeposit = address(this).balance;
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 recordedAfterWithdraw;
        try c.getBalance(address(this)) returns (uint256 __r) { recordedAfterWithdraw = __r; } catch { return; }
        uint contractEtherAfterWithdraw = address(c).balance;
        uint callerEtherAfterWithdraw = address(this).balance;
        assertTrue((reverted && recordedAfterWithdraw == recordedAfterDeposit && contractEtherAfterWithdraw == contractEtherAfterDeposit && callerEtherAfterWithdraw == callerEtherAfterDeposit) ||
            (!reverted && recordedAfterWithdraw == 0 && contractEtherAfterWithdraw == contractEtherAfterDeposit - recordedAfterDeposit && callerEtherAfterWithdraw == callerEtherAfterDeposit + recordedAfterDeposit));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
